('dccf1eba-7989-4ea2-a93a-1adbc606b697', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "32387511-1885-4249-988e-3714ef3ef401", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "93f12d17-d283-44ed-ac45-c07e34636955", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "ef0f3b45-cded-44a6-9382-4ed55c8f313f", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "8a91d042-5371-4747-ac7f-723c176211db", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "be5535bb-3e31-4f59-8119-2df2db5a5c38", "text": "1/5", "isCorrect": false}, {"id": "ef1cd59d-4e1a-4277-a8da-e1095aed1011", "text": "1/2", "isCorrect": false}, {"id": "fa0d09af-d018-40c2-9900-73f8ac24630a", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "00fac468-cb89-4bd6-9854-7f06326c2e8d", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "e1893b3c-587a-4746-9be8-85bf27bf2dae", "text": "Igaz", "isCorrect": true}, {"id": "79d42ad2-4156-4d13-8e66-fe0ee4fa7c0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "99a26a85-52e3-4aa7-9ef9-57ce8f0342b8", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "22ae93b4-3d73-4f09-ada6-66f6a9aa15cc", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "df9ab6e9-4a4e-4701-8464-d5056cae4f6a", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "cbae0ff9-c637-4d2f-8489-6640720ad5f6", "text": "Igaz", "isCorrect": true}, {"id": "0a654229-be53-4f71-ba02-ab023211ddd3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('6aa21684-11da-49b7-9f4b-4d2147553efc', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "57d06629-7b74-4125-8d98-b76dbe2d31c8", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "cb326637-8487-4dd1-9d8d-3df84261d918", "text": "1/3", "isCorrect": true}, {"id": "1b86a5b5-cab6-4973-9f07-071e1581b594", "text": "1/4", "isCorrect": false}, {"id": "479b90dc-511e-415c-a5ca-e1141aabda8f", "text": "2/3", "isCorrect": false}, {"id": "7123c078-843e-4890-9e83-0c34600172d2", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "7d6fc33f-cfb3-47a8-8541-8f772daaa76d", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "9cfef646-d9bb-4844-89d5-bcf7bea8e892", "text": "1/4", "isCorrect": true}, {"id": "63ef3518-731b-4b42-bcc7-d03655325d8a", "text": "1/5", "isCorrect": false}, {"id": "f417ec6a-7014-488c-a68c-cb469f7e2a76", "text": "2/5", "isCorrect": false}, {"id": "7e25fce5-dbd6-473c-ae23-e41fd5f8d489", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "c771ed2d-78fa-4b07-9c44-452473184948", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "65d37756-f4e9-4203-8583-daed9e575113", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "dbdad7e8-a124-48ba-a183-772d240ba7f7", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "71aae914-1555-4323-a33c-0eed3d88679b", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "a3b2487b-f7a9-4a97-a8eb-3361b0ddf95c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56749c11-4db9-430a-804d-17238abec987", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "0614453a-96cc-44ba-812e-9744b3cdda25", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "a148ccfa-761c-4563-90b3-3f8a5a0aaa5a", "text": "Igaz", "isCorrect": true}, {"id": "1f452d5d-93e5-4053-a721-3c0f96cf6b90", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('596a1e98-fb91-4922-ad47-0161ae34d548', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "2d5bf6db-8664-47a9-883a-981af53b0b09", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "585d613d-77fa-4648-9641-bde88ac83f1f", "text": "5/6", "isCorrect": true}, {"id": "451a3462-478b-45af-894f-80af7d769bbc", "text": "3/9", "isCorrect": false}, {"id": "77ea97dd-ee3a-4440-a9d3-0474827ee416", "text": "3/6", "isCorrect": false}, {"id": "8e977db9-7f5e-49b0-adc6-2fec660ab568", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "4730b66e-8f46-4b0b-94e8-f7ad6fcfb8b7", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "ee6a5e35-0552-40e1-9d6c-403cd84355f1", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "b9fb9595-377c-4982-8c26-c64ec8c2994d", "text": "8/11", "isCorrect": false}, {"id": "7433445d-931b-4b8a-bc14-ba8e81e5fb70", "text": "15/11", "isCorrect": false}, {"id": "cd7c0282-4eb6-4bbf-83c9-b309c8c83a28", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "40632874-a82b-44e9-936f-e6d1a7ce7eee", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "9f8b1714-88a8-4449-a2fb-48894d9c7c04", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "34542818-098d-4570-89d8-67cf544aab72", "text": "3/8", "isCorrect": false}, {"id": "881552b6-fd97-41f7-be61-87c22f4e3494", "text": "1/4", "isCorrect": false}, {"id": "3b1f1257-80a2-4a88-abc4-dc801bf8ff35", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "5fcbb8f9-2f48-4615-84d8-b38027a907a2", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "8037406d-faae-4cf9-8076-c06ca78b4482", "text": "9/4", "isCorrect": true}, {"id": "40457818-d776-44b2-8790-d857eff88c60", "text": "-4/9", "isCorrect": false}, {"id": "a4e42222-4a22-40f4-9fbb-61c1d3e3f83d", "text": "1/4", "isCorrect": false}, {"id": "9eacd6d1-9772-463a-bbdc-963fed1558ee", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "7c30e9df-1a1d-45ea-83c9-c1d026e1f751", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "64eb674b-fd8b-40df-bf32-a769393f8d8e", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "b0f9ac34-1315-4e8b-ac1a-94fc9d082bf2", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7b5ea83e-a2ae-4c77-9286-b446f68f4f4e", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "68fdcbc5-ef65-4a51-9afd-b436518bc9d0", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "81da789e-fb63-4417-b07c-027cd2217fa7", "text": "Igaz", "isCorrect": true}, {"id": "163666f5-4118-47d7-a339-f84fe3a89475", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eeda554e-0e82-4aeb-90f1-c07eef88109b", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('26f95dbb-7d14-4202-9b6c-94943235e68e', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "2f041db5-de10-4a84-ab50-fe8cd21bb11f", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "4f2ddf6f-dcbb-4578-b680-4cbec06001b6", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "830c351e-21df-4574-95ed-04358211280d", "text": "A számlálók leírása", "isCorrect": false}, {"id": "3dc26abc-25d9-4e05-b1c3-cfa90674d3c4", "text": "A zárójel használata", "isCorrect": false}, {"id": "21cdcb0f-a26d-4fc7-952f-7d91d4f6e1e5", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "507d0a49-21a9-4557-9f42-4e07a4f1bdac", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "30f25968-27ad-478f-a0e3-97c6af206965", "text": "Igaz", "isCorrect": true}, {"id": "e9cbc931-dbe9-4520-b746-6857d5f09a21", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1fd330de-adbc-49a6-9037-bb9aaaf4ef54", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "d3a45250-5add-433e-8858-8d4c3f71f2e5", "text": "2/5", "isCorrect": true}, {"id": "c69a02a3-e273-4acd-ab2e-cfab606c9d75", "text": "4/10", "isCorrect": false}, {"id": "3fb825fd-a73b-4407-b81c-6b1b46a99d10", "text": "1/5", "isCorrect": false}, {"id": "0fbab748-715a-41e1-970f-b91d359c3630", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "2f64dc76-9db9-41af-9473-a76196119e94", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7560514e-c396-4c0c-a74c-00f049745e3a", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "7dc897fb-8e4f-4cc8-93