('fe19b929-f8b6-484e-83c7-cb09bcc33d9d', '21feff02-016d-46e2-bb9d-c27495133b1b', '48. óra: Síkbeli alakzatok', 'Szögek fajtái, háromszögek csoportosítása, belső szögek összege (180°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "195e37c1-4f19-44cc-a9d4-93d4c341c80b", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "06ee49d9-ffa6-4701-a008-83aefc46aad6", "text": "Milyen szög a 90°-nál kisebb pozitív szög?", "type": "multiple-choice", "options": [{"id": "54e4327a-b0cd-4f94-adbb-90a156fa1697", "text": "Hegyesszög", "isCorrect": true}, {"id": "d5ca4d18-44f9-4c5d-a76e-ab80aee7158d", "text": "Derékszög", "isCorrect": false}, {"id": "feb58b7d-2db9-48f0-86b1-aebc2a8718de", "text": "Tompaszög", "isCorrect": false}, {"id": "1088d6f5-3455-44f3-b924-12632aae70b7", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "359506f2-608c-4871-9bbd-1f580fb9034d", "text": "Milyen szög a pontosan 90°-os szög?", "type": "multiple-choice", "options": [{"id": "5219f6b6-142c-4dd1-bce3-a9a970ebc7b3", "text": "Derékszög", "isCorrect": true}, {"id": "b2f6c6c4-b6e2-4b94-adbb-cd9fa244e450", "text": "Hegyesszög", "isCorrect": false}, {"id": "05b7fcd7-3a9b-4df1-9dca-7de778d38ee9", "text": "Tompaszög", "isCorrect": false}, {"id": "0085ea08-b8a6-4776-80b7-38d0fb6c7d98", "text": "Teljes szög", "isCorrect": false}], "timeLimit": 15}, {"id": "bdb8607e-0889-4383-a1ee-25949bc68bca", "text": "Milyen szög a 90° és 180° közötti szög?", "type": "multiple-choice", "options": [{"id": "6c67ffe1-724f-4877-a776-38fda1601e5e", "text": "Tompaszög", "isCorrect": true}, {"id": "5027afb9-33f7-4a21-82d0-74da159c370e", "text": "Hegyesszög", "isCorrect": false}, {"id": "b62b5893-1631-459f-b33b-271949997cb4", "text": "Derékszög", "isCorrect": false}, {"id": "3fd732cd-72cf-4190-b605-da6be66497e3", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "dbab8228-b6f8-4c3a-a8a7-35352c88644a", "text": "Ha a háromszög két szöge 50° és 60°, mennyi a harmadik szög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "12a43b94-0ad4-4e12-8f35-0da0ec029533", "text": "A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "8f6fface-23d4-4cff-b6e8-f609ac96f959", "text": "Igaz", "isCorrect": true}, {"id": "4133990d-0505-4a32-9efd-a403f442dd71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "934a383b-e4af-4211-b08e-eb4194dcdf62", "text": "A szabályos háromszög (egyenlő oldalú) minden belső szöge 60°-os.", "type": "true-false", "options": [{"id": "fd155eff-36b4-45d6-b89f-9b42b4930bd5", "text": "Igaz", "isCorrect": true}, {"id": "a21fba90-5b0b-4e1c-880e-ec16d9da296c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());